<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$id=(int)($_GET['id']??0);if(!$pdo||$id<1){header('Location: articles.php');exit;}$s=$pdo->prepare('SELECT title FROM articles WHERE id=?');$s->execute([$id]);$a=$s->fetch();if(!$a){header('Location: articles.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();log_admin_activity('article_deleted','Article ID: '.$id);$pdo->prepare('DELETE FROM articles WHERE id=?')->execute([$id]);header('Location: articles.php');exit;}?><!doctype html><html lang="en"><head><meta charset="utf-8"><title>Delete Article</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><section class="card"><h1>Delete article?</h1><p><?=e($a['title'])?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button>Delete permanently</button> <a href="articles.php">Cancel</a></form></section></main></body></html>
